#!/usr/bin/env python3
"""Ливрея Williams (v1.17.43): фигуры в метрах болида -> tools/livery/williams.json (пиксели «фото» по калибровке вида).
   python3 -I tools/livery/williams_gen.py tools/livery/williams.json; затем livery.py -> wrap.js -> livery.py (как у всех команд).
   Фото строго сбоку нет — «фото» сбоку = ортоснимок модели (williams/side_model.png), рисунок — по 3/4 спереди и сзади;
   границы зон понтона — по форме понтона W17 (справка лучом: плечо понтона у W17 ниже и к корме падает 0.63 -> 0.37 м)."""
import json,sys
OUT=sys.argv[1]
SP,SCX,SCY=200,300,420       # сбоку: ортоснимок модели (ortho.js), пикс/м, ступица переднего колеса
TP,TCX,TCY=200.3,302,349     # сверху: фото команды, калибровка по ступицам (база 681 пикс = 3.40 м), силуэт W17 лёг без поправок
sd=lambda z,y:[round(SCX+(1.80-z)*SP,1),round(SCY-(y-0.355)*SP,1)]
tp=lambda z,x:[round(TCX+(1.80-z)*TP,1),round(TCY-x*TP,1)]
P=lambda f,pts:[f(*q) for q in pts]
top=[];side=[]
# ---- сбоку (база — тёмно-синяя: нос, шасси, капот, плавник)
side.append({"c":"ink","note":"карбон под понтоном и низ шасси между передним колесом и понтоном (на фото — чёрный дефлектор, место KEEPER), за понтоном — низ капота над задним колесом",
  "p":P(sd,[(1.45,0.40),(0.50,0.40),(0.0,0.36),(-0.5,0.34),(-1.15,0.31),(-1.76,0.50),(-1.76,-0.1),(1.45,-0.1)])})
side.append({"c":"ink","note":"чёрный верх воздухозаборника и дуги безопасности (место DURACELL)",
  "p":P(sd,[(0.08,1.3),(0.08,0.99),(-0.20,0.955),(-0.40,0.94),(-0.52,0.985),(-0.52,1.3)])})
# понтон: голубая полоса и белое поле — каждая зона своим поясом (верх и низ — там, где луч поперёк попадает в кузов), иначе перенос на вид сверху теряет край.
# B — низ понтона W17 (справка лучом: ниже краски нет), W — верх белого, T — верх голубого (высоты — как на фото; у W17 понтон ниже — к корме голубое и белое ложатся и на бок капота)
B=[(0.52,0.46),(0.15,0.455),(0.05,0.415),(-0.50,0.405),(-0.80,0.40),(-1.00,0.36),(-1.15,0.36)]
W=[(0.20,0.455),(0.13,0.47),(0.04,0.50),(-0.10,0.515),(-0.30,0.53),(-0.70,0.56),(-1.10,0.578),(-1.22,0.575)]
T=[(0.52,0.70),(0.30,0.69),(0.0,0.67),(-0.50,0.64),(-1.00,0.615),(-1.22,0.60),(-1.28,0.585)]
side.append({"c":"lblue","wrap":True,"note":"голубой верх понтона от входа к корме (место Barclays): у входа — во всю высоту, к корме — полоса над белым",
  "p":P(sd,[(0.52,0.46)]+T+W[::-1]+[(0.15,0.455)])})
side.append({"c":"white","wrap":True,"note":"белый низ понтона (место KOMATSU): передний край скошен, к корме белое растёт вверх до 0.58 м, голубое сужается в полосу",
  "p":P(sd,W+[(-1.25,0.555),(-1.20,0.50)]+[q for q in B[::-1] if q[0]<=0.15])})
side.append({"c":"purple","note":"щиток заднего крыла: верх спереди — сине-фиолетовая панель (место KOMATSU)","p":P(sd,[(-1.76,1.3),(-1.76,0.78),(-2.08,0.78),(-2.08,1.3)])})
side.append({"c":"lblue","note":"щиток заднего крыла: верх сзади — голубой, как верхний закрылок (место Barclays; закрылок смотрит назад и берёт карту «сбоку» на четверть)","p":P(sd,[(-2.08,1.3),(-2.08,0.80),(-2.5,0.80),(-2.5,1.3)])})
side.append({"c":"white","note":"щиток заднего крыла: белая панель под ними до низа","p":P(sd,[(-1.76,0.78),(-2.08,0.78),(-2.08,0.80),(-2.5,0.80),(-2.5,0.30),(-1.76,0.30)])})
# ---- сверху
top.append({"c":"ink","note":"переднее крыло: щитки и всё снаружи закрылков — карбон (на фото чёрные с ATLASSIAN)","p":P(tp,[(3.4,0.62),(3.4,1.0),(2.15,1.0),(2.15,0.62)])})
top.append({"c":"white","note":"кончики закрылков переднего крыла — белые (на фото белая передняя часть крыла с kraken; у W17 краска — только кончики закрылков)","p":P(tp,[(3.4,0.45),(3.4,0.62),(2.15,0.62),(2.15,0.45)])})
top.append({"c":"ink","note":"чёрный верх воздухозаборника за дугой (место DURACELL), скруглён к корме",
  "p":P(tp,[(0.08,0.0),(0.08,0.17),(-0.10,0.20),(-0.30,0.18),(-0.45,0.13),(-0.52,0.06),(-0.53,0.0)])})
top.append({"c":"ink","note":"заднее крыло: основная плоскость сверху — карбон (ATLASSIAN на чёрном)","p":P(tp,[(-1.76,0.0),(-1.76,1.0),(-2.10,1.0),(-2.10,0.0)])})
top.append({"c":"lblue","note":"заднее крыло: верхний закрылок голубой (на фото сзади — BARCLAYS на голубом; сверху его передняя часть чёрная — проекция не различает, как синий закрылок Ferrari)","p":P(tp,[(-2.10,0.0),(-2.10,1.0),(-2.5,1.0),(-2.5,0.0)])})
cfg={"key":"williams","team":"Williams","color":"#7EC8FF","halo":"#121620",
 "src":"FW48 2026 по 6 фото владельца 05.11.2026 (сверху, сзади, 3/4 спереди, 3/4 сзади, спереди, кокпит; строго сбоку нет — «фото» сбоку — ортоснимок модели), стилизация; надписи и логотипы не переносятся",
 "palette":{"blue":["#0a2470",0.15],"ink":["#16171a",0.15],"lblue":["#3a8ec8",0.1],"white":["#b4b8c0",0.3],"purple":["#140c5a",0.2]},
 "num":{"w":0.09,"o":0,"nose":"#e8eaee","side":"#e8eaee","hn":0.15,"hs":0.11,"note":"белые цифры заливкой, прямые («23» на носу, как на фото)"},
 "base":"blue","layers":["ink","lblue","white","purple"],
 "top":{"photo":"williams/top.jpg","ppm":TP,"cx":TCX,"cy":TCY,"note":"фото команды сверху, нос влево; калибровка по ступицам (база 681 пикс = 3.40 м), силуэт W17 ортокамерой лёг без поправок","shapes":top},
 "side":{"photo":"williams/side_model.png","ppm":SP,"cx":SCX,"cy":SCY,"note":"фото строго сбоку нет: «фото» — ортоснимок модели W17 (ortho.js), фигуры — по 3/4 спереди и сзади","shapes":side}}
s=json.dumps(cfg,ensure_ascii=False).replace('{"c"','\n   {"c"')
open(OUT,'w').write(s);print(len(top),len(side))
